-- Ajustes generales (punto de inicio de los recorridos, etc.)
CREATE TABLE IF NOT EXISTS ajuste (
  clave      VARCHAR(40) PRIMARY KEY,
  valor      JSON NOT NULL,
  CHECK (JSON_VALID(valor))
) ENGINE=InnoDB;
INSERT IGNORE INTO ajuste (clave, valor) VALUES ('inicio_recorrido', '{"x":1620,"y":45,"nombre":"Acceso principal"}');
-- Itinerario diario del inspector
CREATE TABLE IF NOT EXISTS itinerario (
  id_itinerario INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  fecha         DATE NOT NULL,
  id_usuario    INT UNSIGNED NOT NULL,
  modo          ENUM('vehiculo','pie') NOT NULL,
  inicio        JSON NOT NULL,                 -- {x, y, nombre}
  volver        BOOLEAN NOT NULL DEFAULT FALSE,
  km_plan       DECIMAL(6,2) NOT NULL,
  minutos_plan  SMALLINT UNSIGNED NOT NULL,
  geometria     JSON NOT NULL,                 -- trazo por tramo entre paradas
  estado        ENUM('activo','terminado','reemplazado') NOT NULL DEFAULT 'activo',
  creado        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  cerrado       DATETIME NULL,
  FOREIGN KEY (id_usuario) REFERENCES usuario(id_usuario),
  INDEX ix_itinerario_usuario (id_usuario, fecha, estado)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS itinerario_parada (
  id_itinerario INT UNSIGNED NOT NULL,
  orden         SMALLINT UNSIGNED NOT NULL,
  tipo          ENUM('uf','marca') NOT NULL,
  ref           VARCHAR(20) NOT NULL,          -- "1203" o "1203/1204" (lote unificado) o "M-0003"
  x             DECIMAL(7,1) NOT NULL,
  y             DECIMAL(7,1) NOT NULL,
  fijada        BOOLEAN NOT NULL DEFAULT FALSE,
  estado        ENUM('pendiente','hecha','salteada') NOT NULL DEFAULT 'pendiente',
  marcada       DATETIME NULL,
  km_desde_anterior DECIMAL(6,2) NOT NULL DEFAULT 0,
  PRIMARY KEY (id_itinerario, orden),
  FOREIGN KEY (id_itinerario) REFERENCES itinerario(id_itinerario) ON DELETE CASCADE
) ENGINE=InnoDB;
